using Mutagen.Bethesda.Plugins;
using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Furniture.BenchTypes lacked xEdit's 10 Extractor and Furniture.Flag lacked xEdit's bit 0x01 ("Unknown 0").
// Neither value occurs in Starfield.esm or the official DLC masters (WBDT 0/2/5/7/9/11, FNAM 0 and 2 only), so the
// last test sets them on real subrecords; the others read real records unchanged.
public class FurnitureBenchTypeFlagTests
{
    // WorkbenchResearch (01A21B:Starfield.esm), minus FULL (a localized string ID this unlocalized test reader would read
    // as text): WBDT 11 Research, FNAM 0, JNAM/GNAM 180
    private const string Research = "";

    private static IEnumerable<IFurnitureGetter> Read(byte[] bytes)
        => ReadBoth<IFurnitureGetter>(bytes, f => Furniture.CreateFromBinary(f), (s, p) => FurnitureBinaryOverlay.FurnitureFactory(s, p));

    [Fact]
    public void ResearchBench_WholeRecord()
    {
        foreach (var furn in Read(Record("FURN", Hex(Research))))
        {
            furn.BenchType.ShouldBe(Furniture.BenchTypes.Research);
            furn.Flags.ShouldBe((Furniture.Flag)0);
            furn.ActivationAngleForPlayer.ShouldBe((ushort)180);
            var written = GameConstants.Starfield.MajorRecord(Write(w => furn.WriteToBinary(w)));
            written.Content.ToArray().ShouldBe(Hex(Research));
        }
    }

    [Fact]
    public void IgnoredBySandbox()
    {
        // FNAM of MQ101_035_SarahMorganScene_SarahFurnitureMarker (0008A6:Starfield.esm)
        foreach (var furn in Read(Record("FURN", Subrecord("FNAM", "0200"))))
        {
            furn.Flags.ShouldBe(Furniture.Flag.IgnoredBySandbox);
            var written = GameConstants.Starfield.MajorRecord(Write(w => furn.WriteToBinary(w)));
            written.FindSubrecord(new RecordType("FNAM")).Content.ToArray().ShouldBe(Hex("0200"));
        }
    }

    [Fact]
    public void Extractor_AndUnknown0()
    {
        ((int)Furniture.BenchTypes.Extractor).ShouldBe(10);
        ((int)Furniture.Flag.Unknown0).ShouldBe(1);
        foreach (var furn in Read(Record("FURN", Subrecord("FNAM", "0300"), Subrecord("WBDT", "0A"))))
        {
            furn.Flags.ShouldBe(Furniture.Flag.Unknown0 | Furniture.Flag.IgnoredBySandbox);
            furn.BenchType.ShouldBe(Furniture.BenchTypes.Extractor);
            var written = GameConstants.Starfield.MajorRecord(Write(w => furn.WriteToBinary(w)));
            written.FindSubrecord(new RecordType("FNAM")).Content.ToArray().ShouldBe(Hex("0300"));
            written.FindSubrecord(new RecordType("WBDT")).Content.ToArray().ShouldBe(Hex("0A"));
        }
    }
}
